function parse(text2) {
  const out = {};
  let current = null;
  for (const line of text2.split("\n")) {
    if (line.trim() === "") continue;
    const words = line.trim().split(/\s+/);
    if (line.startsWith("  ")) {
      current.push(...words);
      continue;
    }
    current = out[words[0]] = words.slice(1);
  }
  return out;
}
var PART_WORD_TAILS_BY_ENDING = parse(TABLE);

