  // chose, the tail's turn count, and how long a doorbell waited for its visit. Integers from a
  // clock and closed section names, naming no mailbox content.
  "rotationMs",
  "tailMs",
  "tailWallMs",
  "turns",
  "sections",
  "section",
  "ms",
  "wakeLatencyMs",
