  "pgliteOpenMs",
  "adoptBaselineMs",
  "migrateMs",
  "worldMs",
  "totalReadyMs",
  // …and `treeSyncMs`: a new store's one sync of its files, a `Date.now()` delta (0 on a reopen).
  "treeSyncMs",
