  "loopDelayP99Ms",
  "loopDelayMaxMs",
  "loopReading",
  "loopUtilization",
  "storeFsyncs",
  "storeFsyncMs",
  "fsyncs",
  // ── retry, failure and circuit accounting ──
  "attempt",
  "attempts",
  "consecutiveFailures",
  "maxSyncFailures",
  "consecutiveFaults",
  "opens",
  "open",
  "threshold",
  "circuit",
  "cooldownMs",
  "retryAt",
  "retryInMs",
