  "retainedBytes",
  "processRetainedBytes",
  "processBudgetBytes",
  // ── alerting (the worker's alert loop and the API's internal alert route) ──
  "alertKey",
  "alertKeys",
  "alertSinks",
  "alertIntervalMs",
  "rosterIntervalMs",
  "pollIntervalMs",
